import{boot,e,field,editAttrs}from'../creative-kit/ui.js?v=0.8.0';import{make,validate,apply,markdown,names}from'./state.js?v=0.8.0';
function render(w){return `<div class="phase-tabs toolbar"><button data-action="phase" data-phase="generate" aria-pressed="${w.phase==='generate'}">1 · Generate three mechanisms</button><button data-action="phase" data-phase="compare" aria-pressed="${w.phase==='compare'}">2 · Compare their consequences</button></div><div class="section-head"><div><h2>${w.phase==='generate'?'The third answer changes the way it works.':'Different mechanisms accept different costs.'}</h2><p>${w.phase==='generate'?'A gives you a starting point. B improves a part. Q changes the underlying mechanism. Drag strengths between answers when you want to borrow deliberately.':'Choose useful criteria before selecting a test. Borrowing a strength does not automatically preserve it; explain the transfer.'}</p></div></div>${w.phase==='compare'?field('criteria','What should distinguish a useful answer?',w.criteria,editAttrs('workspace','','criteria')):''}<div class="answer-grid">${Object.entries(w.answers).map(([key,a])=>`<section class="panel answer ${key}" data-drop-id="${key}"><div class="card-top"><span>${names[key]}</span>${w.chosen===key?'<span class="tag">To test</span>':''}</div><h2>${e(a.title||'Name the approach')}</h2>${w.phase==='generate'?`${field(`${key}-title`,'Approach',a.title,editAttrs('answers',key,'title'))}${field(`${key}-mechanism`,'How does it produce the result?',a.mechanism,editAttrs('answers',key,'mechanism'))}${key!=='a'?field(`${key}-difference`,key==='q'?'What makes the mechanism different?':'Which part of A does this improve?',a.difference,editAttrs('answers',key,'difference')):''}`:`<p class="mechanism">${e(a.mechanism||'Mechanism not described yet.')}</p>${field(`${key}-assessment`,'What happens under the chosen criteria?',a.assessment,editAttrs('answers',key,'assessment'),'Keep observations separate from predictions.')}`}
<div class="strength-token" data-drag-id="${key}"><div class="card-top"><span>STRENGTH TO BORROW</span><button class="drag-handle" data-drag-handle data-action="borrow-menu" data-from="${key}" aria-label="Borrow strength from ${key.toUpperCase()}">⠿</button></div>${field(`${key}-strength`,'What is worth keeping?',a.strength,editAttrs('answers',key,'strength'))}<button class="text-button" data-action="borrow-menu" data-from="${key}">Borrow in another answer ↗</button></div>${a.borrowed.length?`<div class="borrowed">${a.borrowed.map(b=>`<p><strong>From ${b.from.toUpperCase()}:</strong> ${e(b.text||'Unnamed strength')}${b.stale?' <span class="tag amber">Source changed · recheck</span>':''}<button class="text-button" data-action="unborrow" data-from="${b.from}" data-to="${key}">Remove link</button></p>`).join('')}</div>`:'<p class="hint">Drop a strength here to keep its source visible.</p>'}${field(`${key}-weakness`,'What does this still sacrifice?',a.weakness,editAttrs('answers',key,'weakness'))}${w.phase==='compare'?`<button class="${w.chosen===key?'primary':''}" data-action="choose" data-id="${key}">${w.chosen===key?'Selected for a test':'Try this approach'}</button>`:''}</section>`).join('')}</div>${w.phase==='compare'?`<section class="panel test-plan"><h2>${w.chosen?`A test of ${w.chosen.toUpperCase()}`:'A small test before commitment'}</h2><div class="two-col">${field('test','What will you try?',w.test,editAttrs('workspace','','test'))}${field('learn','What would change your mind?',w.learn,editAttrs('workspace','','learn'))}</div></section>`:''}`;}
boot({route:'answers',code:'S06',title:'Three genuinely different answers',description:'Escape cosmetic variations of the first idea. Keep three working approaches in view.',make,validate,apply,markdown,render,drop:(from,to,k)=>{if(from!==to)k.act({type:'borrow',from,to});},handle:(a,d,k)=>{if(a==='borrow-menu')k.open('<div class="dialog-options">'+Object.entries(names).filter(([key])=>key!==d.from).map(([key,label])=>`<button data-action="borrow" data-from="${d.from}" data-to="${key}">${label}</button>`).join('')+'</div>','Borrow this strength');else if(a==='borrow'){k.close();k.act({type:a,from:d.from,to:d.to});}else if(a==='unborrow')k.act({type:a,from:d.from,to:d.to});else if(a==='choose')k.act({type:a,id:d.id});else if(a==='phase')k.act({type:a,phase:d.phase},{checkpoint:false});}});
